#!/usr/bin/env bash
# Gate `pass-by-value-lint-on` for [R:borrow-in-signatures], generated by relearn from the rule file.
# Edit the rule, never this script: `relearn verify` reports a hand edit.
# Engine: lint-enabled. Records: source, lint, level, tab-separated.
#   bash pass-by-value-lint-on.sh <repository root>   0 clean, 1 finding, 2 could not check
#   bash pass-by-value-lint-on.sh --judge < records   0 clean, 1 hit (the fixture runner)
# A `warn` gate prints its finding and exits 0.
set -uo pipefail
export LC_ALL=C

name='pass-by-value-lint-on'
tag='R:borrow-in-signatures'
message='clippy'\''s needless_pass_by_value is not switched on, so an owned parameter the body only reads compiles silently. Set it, or clippy::pedantic, to warn or deny in [lints.clippy] of Cargo.toml (or [workspace.lints.clippy]), and keep it out of any allow.'
export RL_FILES='((^|/)Cargo\.toml$)|((^|/)src/lib\.rs$)|((^|/)src/main\.rs$)'
export RL_EXCLUDE=''
export RL_LINT='clippy::needless_pass_by_value'
export RL_GROUPS='clippy::pedantic'
export RL_DEFAULT='allow'

# Judge: 3 field(s) per record on stdin. 0 clean, 1 hit, 3 unreadable.
judge() {
  awk '
BEGIN {
  FS = "\t"
  files = ENVIRON["RL_FILES"]
  excl = ENVIRON["RL_EXCLUDE"]
  hits = 0
  bad = 0
  lint = ENVIRON["RL_LINT"]
  n = split(ENVIRON["RL_GROUPS"], g, " ")
  for (i = 1; i <= n; i++) grp[g[i]] = 1
  def = ENVIRON["RL_DEFAULT"]
}
$0 == "" { next }
NF != 3 { bad = 1; next }
$1 !~ files { next }
excl != "" && $1 ~ excl { next }
{
  on = ($3 == "warn" || $3 == "deny" || $3 == "forbid")
  off = ($3 == "allow" || $3 == "expect")
  if ($2 == lint) { if (on) non = 1; if (off) noff = 1 }
  else if ($2 in grp) { if (on) gon = 1; if (off) goff = 1 }
}
END {
  if (bad) exit 3
  enabled = !noff && (non || gon || (def == "warn" && !goff))
  if (!enabled) { print lint " is not enabled"; exit 1 }
  exit 0
}
'
}

# Collect: lint levels from `[lints.clippy]`, `[lints.rust]` and their
# `workspace.` forms in every TOML file in scope, and from single-line
# crate-root `#![level(lint, ...)]` attributes in every Rust file in scope.
# A level given on the command line (`cargo clippy -- -W ...`) is not seen.
collect() {
  (
    cd "$1" || exit 1
    git ls-files -z | tr '\0' '\n' > "$work/paths.nl" || exit 1
    grep -E -- "$RL_FILES" "$work/paths.nl" > "$work/scoped" || true
    if [ -n "$RL_EXCLUDE" ]; then
      grep -vE -- "$RL_EXCLUDE" "$work/scoped" > "$work/kept" || true
    else
      cp "$work/scoped" "$work/kept"
    fi
    while IFS= read -r p; do
      [ -f "$p" ] || continue
      RL_PATH="$p" awk '
BEGIN { p = ENVIRON["RL_PATH"]; toml = (p ~ /\.toml$/) }
{ sub(/\r$/, "") }
toml && /^[ \t]*#/ { next }
toml && /^[ \t]*\[/ { t = $0; sub(/#.*/, "", t); gsub(/[ \t]/, "", t); table = t; next }
toml && (table == "[lints.clippy]" || table == "[workspace.lints.clippy]" || table == "[lints.rust]" || table == "[workspace.lints.rust]") && /=/ {
  key = $0; sub(/=.*/, "", key); gsub(/[ \t"]/, "", key); gsub(/-/, "_", key)
  val = $0; sub(/^[^=]*=/, "", val)
  if (match(val, /"(allow|expect|warn|deny|forbid)"/)) {
    prefix = (table ~ /clippy/) ? "clippy::" : ""
    print p "\t" prefix key "\t" substr(val, RSTART + 1, RLENGTH - 2)
  }
  next
}
!toml && /^[ \t]*#!\[(allow|expect|warn|deny|forbid)\(/ {
  l = $0; sub(/^[ \t]*#!\[/, "", l)
  level = l; sub(/\(.*/, "", level)
  inner = l; sub(/^[a-z]+\(/, "", inner); sub(/\)\].*$/, "", inner)
  n = split(inner, parts, ",")
  for (i = 1; i <= n; i++) { x = parts[i]; gsub(/[ \t]/, "", x); if (x != "") print p "\t" x "\t" level }
}
' "$p"
    done < "$work/kept"
  )
}

if [ "${1:-}" = "--judge" ]; then
  judge
  exit $?
fi

disarmed() {
  printf '[%s] %s: DISARMED (exit 2, not a pass): %s\n' "$tag" "$name" "$1" >&2
  exit 2
}
root="${1:-.}"
command -v git >/dev/null 2>&1 || disarmed "git is not on PATH"
git -C "$root" rev-parse --is-inside-work-tree >/dev/null 2>&1 \
  || disarmed "$root is not a git checkout"
work="$(mktemp -d)" || disarmed "no scratch directory"
trap 'rm -rf "$work"' EXIT
collect "$root" > "$work/records" || disarmed "the collect stage failed"
judge < "$work/records" > "$work/findings"
case $? in
  0) exit 0 ;;
  1) ;;
  *) disarmed "the judge could not read a record" ;;
esac
count="$(wc -l < "$work/findings" | tr -d ' ')"
printf '[%s] %s: BLOCKED. %s\n' "$tag" "$name" "$message"
printf '%s finding(s) in %s:\n' "$count" "$root"
sed 's/^/  /' "$work/findings"
exit 1

# <!-- relearn:generated v0.1.0 sha256=b73a0955e5cb0e85bbb90bccea59126b126b5dabec1d0dc388f32b7caf7a60ca rules=R:borrow-in-signatures -- DO NOT EDIT; regenerate with `relearn build` -->
